digraph InverseLaws{rankdir=TB; splines=ortho;newrank=true;nodesep=0.6;ranksep=0.8;pad=0.5;node[fontname="Segoe UI, Roboto, Helvetica, Arial, sans-serif",  fontsize=11,  margin=0.15, height=0.0];edge[color="#546E7A",  penwidth=1.5];root[label="Inverse Laws of Robotics
(Human-Centric AI Guidelines)", shape=box,  style="filled,rounded",  fillcolor="#263238",  fontcolor="#FFFFFF",  fontsize=13,  penwidth=0, width=2.5];law1[label="1. Non-Anthropomorphism",  shape=box,  style="filled,rounded",  fillcolor="#ECEFF1",  color="#37474F",  penwidth=2];law2[label="2. Non-Deference",  shape=box,  style="filled,rounded",  fillcolor="#ECEFF1",  color="#37474F",  penwidth=2];law3[label="3. Non-Abdication
of Responsibility",  shape=box,  style="filled,rounded",  fillcolor="#ECEFF1",  color="#37474F",  penwidth=2];l1_d1[label="Do not attribute
emotions or intentions",  shape=note,  style="filled",  fillcolor="#FFF9C4",  color="#FBC02D",  fontsize=9];l1_d2[label="AI is a statistical model,
not a social actor",  shape=note,  style="filled",  fillcolor="#FFF9C4",  color="#FBC02D",  fontsize=9];l2_d1[label="Do not blindly trust
AI output",  shape=note,  style="filled",  fillcolor="#B2DFDB",  color="#00897B",  fontsize=9];l2_d2[label="Verify independently;
No peer review exists",  shape=note,  style="filled",  fillcolor="#B2DFDB",  color="#00897B",  fontsize=9];l3_d1[label="Humans accountable
for consequences",  shape=note,  style="filled",  fillcolor="#FFCCBC",  color="#FF5722",  fontsize=9];l3_d2[label="No excuse:
'The AI told me to do it'",  shape=note,  style="filled",  fillcolor="#FFCCBC",  color="#FF5722",  fontsize=9];root->{law1, law2, law3}[weight=3];law1->{l1_d1, l1_d2};law2->{l2_d1, l2_d2};law3->{l3_d1, l3_d2};{rank=same;law1;law2;law3;}{rank=same;l1_d1;l2_d1;l3_d1;}{rank=same;l1_d2;l2_d2;l3_d2;}}
